html:
{%- set c = frappe.get_doc("BF Contract", doc.contract) -%}
{%- set company = frappe.db.get_value("Project", doc.project, "company") if doc.project else "" -%}
{%- set project_name = frappe.db.get_value("Project", doc.project, "project_name") if doc.project else "" -%}
{%- set current_end = c.revised_completion_date or c.original_completion_date -%}
{%- set new_end = frappe.utils.add_days(current_end, doc.days_requested) if current_end else None -%}
{%- set d = frappe.utils.formatdate -%}
<style>
	.eot-letter { font-size: 11.5px; line-height: 1.55; color: #111; }
	.eot-letter .meta td { padding: 1px 12px 1px 0; vertical-align: top; }
	.eot-letter h3 { font-size: 12.5px; text-decoration: underline; margin: 16px 0 10px; }
	.eot-letter .facts td { padding: 2px 14px 2px 0; }
	.eot-letter .sign { margin-top: 36px; }
</style>
<div class="eot-letter">
	<table class="meta">
		<tr><td>{{ _("Our Ref") }}:</td><td><b>{{ doc.reference_no or doc.name }}</b></td></tr>
		<tr><td>{{ _("Date") }}:</td><td>{{ d(doc.request_date) if doc.request_date else d(frappe.utils.today()) }}</td></tr>
	</table>
	<p style="margin-top:14px">
		{{ c.customer or "" }}<br>
		{%- if c.consultant %}{{ _("Attn") }}: {{ c.consultant }}<br>{% endif %}
	</p>
	<h3>{{ _("REQUEST FOR EXTENSION OF TIME") }} – {{ _("CONTRACT NO.") }} {{ c.name }}{% if project_name %}: {{ project_name | upper }}{% endif %}</h3>
	<p>{{ _("Dear Sir/Madam,") }}</p>
	<p>{{ _("We refer to the above contract, which commenced on {0} with a completion date of {1}.").format(d(c.start_date) if c.start_date else "-", d(c.original_completion_date) if c.original_completion_date else "-") }}
	{%- if c.revised_completion_date and c.revised_completion_date != c.original_completion_date %}
		{{ _("Extensions already granted have moved the completion date to {0}.").format(d(c.revised_completion_date)) }}
	{%- endif %}</p>
	<p>{{ _("We hereby request an extension of time of {0} days, moving the completion date to {1}, for the following reasons:").format("<b>" ~ doc.days_requested ~ "</b>", "<b>" ~ (d(new_end) if new_end else "-") ~ "</b>") }}</p>
	<div style="margin:6px 0 10px 18px">{{ doc.reason or "" }}</div>
	<table class="facts">
		<tr><td>{{ _("Current completion date") }}:</td><td>{{ d(current_end) if current_end else "-" }}</td></tr>
		<tr><td>{{ _("Extension requested") }}:</td><td>{{ doc.days_requested }} {{ _("days") }}</td></tr>
		<tr><td>{{ _("Requested completion date") }}:</td><td><b>{{ d(new_end) if new_end else "-" }}</b></td></tr>
	</table>
	<p style="margin-top:10px">{{ _("The supporting documents are attached. We look forward to your approval.") }}</p>
	<p>{{ _("Yours faithfully,") }}</p>
	<div class="sign">
		<p>.....................................................<br>
		{{ _("For and on behalf of") }} <b>{{ company or "" }}</b><br>
		{{ _("Name") }}: ......................................................<br>
		{{ _("Designation") }}: ...............................................</p>
	</div>
</div>
